-- Owner-controlled product presentation and pre-order merchandising.
ALTER TABLE product_details ADD COLUMN homepage_showcase INTEGER NOT NULL DEFAULT 0 CHECK(homepage_showcase IN (0,1));
ALTER TABLE product_details ADD COLUMN price_notice INTEGER NOT NULL DEFAULT 0 CHECK(price_notice IN (0,1));
ALTER TABLE product_details ADD COLUMN price_unconfirmed INTEGER NOT NULL DEFAULT 0 CHECK(price_unconfirmed IN (0,1));
ALTER TABLE product_details ADD COLUMN preorder_slideshow INTEGER NOT NULL DEFAULT 0 CHECK(preorder_slideshow IN (0,1));
ALTER TABLE product_details ADD COLUMN preorder_banner_key TEXT NOT NULL DEFAULT '';
ALTER TABLE product_details ADD COLUMN preorder_headline TEXT NOT NULL DEFAULT '';
ALTER TABLE product_details ADD COLUMN preorder_body TEXT NOT NULL DEFAULT '';
ALTER TABLE product_details ADD COLUMN showcase_image_key TEXT NOT NULL DEFAULT '';
ALTER TABLE product_details ADD COLUMN showcase_style TEXT NOT NULL DEFAULT 'cutout' CHECK(showcase_style IN ('cutout','cover'));
ALTER TABLE product_details ADD COLUMN case_platform TEXT NOT NULL DEFAULT '';
UPDATE product_details SET homepage_showcase=1 WHERE product_id IN (SELECT id FROM products WHERE featured=1 AND product_type IN ('controller','physical-game'));
UPDATE product_details SET homepage_showcase=1 WHERE EXISTS(SELECT 1 FROM homepage_sections h WHERE h.section_key IN ('controllers','games') AND json_valid(h.settings_json) AND instr(','||coalesce(json_extract(h.settings_json,'$.productIds'),'')||',',','||product_details.product_id||',')>0);
UPDATE product_details SET price_notice=1 WHERE product_id IN (SELECT id FROM products WHERE product_type='console' AND (slug LIKE 'ps5-%' OR lower(name) LIKE 'playstation 5%'));
UPDATE products SET category_id=(SELECT id FROM categories WHERE slug='consoles') WHERE category_id=(SELECT id FROM categories WHERE slug='retro') AND id IN (SELECT product_id FROM product_details WHERE generation IN ('PS2','PS3','Xbox 360'));
UPDATE categories SET description='Retro game sticks, mini consoles and arcade systems.' WHERE slug='retro';
INSERT INTO site_settings(key,value) VALUES('preorders_enabled','true') ON CONFLICT(key) DO UPDATE SET value=excluded.value;

